package com.andye.warmod.block;import com.andye.warmod.block.entity.RadarStationBlockEntity;import com.andye.warmod.item.ModItems;import com.andye.warmod.radar.station.RadarStationManager;import java.util.*;import net.minecraft.core.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.BlockState;public final class RadarStationStructure {private static final Set<String>TEARDOWN=new HashSet<>();private RadarStationStructure(){}public static BlockPos position(BlockPos centre,RadarStationPart part,Direction facing){return centre.offset(part.offset(facing));}public static boolean complete(ServerLevel level,BlockPos centre,Direction facing){for(var part:RadarStationPart.values()){BlockState s=level.getBlockState(position(centre,part,facing));if(!s.is(ModBlocks.RADAR_STATION)||s.getValue(RadarStationBlock.PART)!=part||s.getValue(RadarStationBlock.FACING)!=facing)return false;}return level.getBlockEntity(centre)instanceof RadarStationBlockEntity;}public static void teardown(ServerLevel level,BlockPos any,BlockState state,boolean drop){if(!state.is(ModBlocks.RADAR_STATION))return;Direction facing=state.getValue(RadarStationBlock.FACING);BlockPos centre=state.getValue(RadarStationBlock.PART).resolveCentre(any,facing);String key=level.dimension().identifier()+":"+centre.asLong();synchronized(TEARDOWN){if(!TEARDOWN.add(key))return;}try{RadarStationBlockEntity be=level.getBlockEntity(centre)instanceof RadarStationBlockEntity r?r:null;if(be!=null){be.setTeardownInProgress(true);RadarStationManager.unregister(level,be);}if(drop)Block.popResource(level,centre,new ItemStack(ModItems.RADAR_STATION));for(var part:RadarStationPart.values()){BlockPos p=position(centre,part,facing);if(level.getBlockState(p).is(ModBlocks.RADAR_STATION))level.setBlock(p,Blocks.AIR.defaultBlockState(),Block.UPDATE_ALL);}if(be!=null)be.setTeardownInProgress(false);}finally{synchronized(TEARDOWN){TEARDOWN.remove(key);}}}}